1	"use client";
2	
3	import { useEffect, useRef } from "react";
4	
5	const VERTEX_SRC = `
6	attribute vec2 a_position;
7	void main() {
8	  gl_Position = vec4(a_position, 0.0, 1.0);
9	}
10	`;
11	
12	// Weicher, langsamer Verlauf aus Value-Noise statt teurer Simplex-Noise:
13	// reicht für einen ruhigen Hintergrund und kostet kaum GPU-Zeit.
14	const FRAGMENT_SRC = `
15	precision highp float;
16	uniform vec2 u_resolution;
17	uniform float u_time;
18	
19	float hash(vec2 p) {
20	  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
21	}
22	
23	float noise(vec2 p) {
24	  vec2 i = floor(p);
25	  vec2 f = fract(p);
26	  vec2 u = f * f * (3.0 - 2.0 * f);
27	  return mix(
28	    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
29	    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
30	    u.y
31	  );
32	}
33	
34	vec3 hsv2rgb(vec3 c) {
35	  vec4 k = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
36	  vec3 p = abs(fract(c.xxx + k.xyz) * 6.0 - k.www);
37	  return c.z * mix(k.xxx, clamp(p - k.xxx, 0.0, 1.0), c.y);
38	}
39	
40	void main() {
41	  vec2 uv = gl_FragCoord.xy / u_resolution.xy;
42	  vec2 p = uv * 3.0;
43	
44	  float n = 0.0;
45	  n += noise(p + u_time * 0.35) * 0.6;
46	  n += noise(p * 2.0 - u_time * 0.58) * 0.4;
47	
48	  // Dunkles Navy als Basis; Hue wandert nur leicht, damit es Blau bleibt
49	  // und nicht wie ein Regenbogen-Effekt wirkt.
50	  float hue = 0.62 + sin(u_time * 0.4) * 0.03;
51	  float lightness = mix(0.2, 0.6, n);
52	  vec3 color = hsv2rgb(vec3(hue, 0.7, lightness));
53	
54	  // Heller diagonaler Balken, der über den Screen wandert (wrap-around für
55	  // nahtlose Wiederholung statt eines harten Sprungs am Rand).
56	  float diag = (uv.x + uv.y) * 0.5;
57	  float barPos = fract(u_time * 0.06);
58	  float dist = abs(diag - barPos);
59	  dist = min(dist, 1.0 - dist);
60	  float bar = smoothstep(0.05, 0.0, dist) * 0.2;
61	  color += bar;
62	
63	  gl_FragColor = vec4(color, 1.0);
64	}
65	`;
